function encodeRFC3986(value) {
  return encodeURIComponent(value).replace(/[!'()*]/g, function (character) {
    return "%" + character.charCodeAt(0).toString(16).toUpperCase();
  });
}

function assertPlainObject(value) {
  if (value === null || typeof value !== "object") {
    throw new TypeError();
  }

  const prototype = Object.getPrototypeOf(value);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new TypeError();
  }
}

function assertDenseStringArray(value) {
  if (!Array.isArray(value)) {
    throw new TypeError();
  }

  for (let index = 0; index < value.length; index += 1) {
    if (
      !Object.prototype.hasOwnProperty.call(value, index) ||
      typeof value[index] !== "string"
    ) {
      throw new TypeError();
    }
  }
}

function serializeSections(sections) {
  assertPlainObject(sections);

  const pairs = [];

  for (const sectionName of Object.keys(sections)) {
    const section = sections[sectionName];

    if (section === undefined) {
      continue;
    }

    assertPlainObject(section);
    const encodedSectionName = encodeRFC3986(sectionName);

    for (const fieldName of Object.keys(section)) {
      const values = section[fieldName];

      if (values === undefined) {
        continue;
      }

      assertDenseStringArray(values);

      const encodedName =
        encodedSectionName + "%5B" + encodeRFC3986(fieldName) + "%5D";

      for (let index = 0; index < values.length; index += 1) {
        pairs.push([encodedName, encodeRFC3986(values[index])]);
      }
    }
  }

  pairs.sort(function (left, right) {
    if (left[0] < right[0]) return -1;
    if (left[0] > right[0]) return 1;
    if (left[1] < right[1]) return -1;
    if (left[1] > right[1]) return 1;
    return 0;
  });

  return pairs
    .map(function (pair) {
      return pair[0] + "=" + pair[1];
    })
    .join("&");
}
